\label{Qn:main2}
Let $t$ be a Fock covariant representation of a product system $X$ over $P$.
\begin{enumerate}
\item Under which conditions on $P$ and $X$ is exactness or nuclearity of $\mathrm{C}^*(t)$ equivalent to exactness or nuclear embeddability of the cores $\mathbf{K}_{{\mathbf{x}}, t_\ast}$ for all ${\mathbf{x}} \in {\mathcal{J}}$? 
\item Under which conditions on $P$ and $X$ is exactness or nuclear embeddability of the cores $\mathbf{K}_{{\mathbf{x}}, t_\ast}$ for all ${\mathbf{x}} \in {\mathcal{J}}$ equivalent to exactness or nuclear embeddability of the coefficient C*-algebra $A$? 
\end{enumerate}

\cite[Proposition 3.7.6]{BO08}\label{P:localsplit} 
Let ${\mathcal{A}}$ be a C*-algebra and for an ideal ${\mathcal{J}} \lhd {\mathcal{A}}$ let
\begin{equation*}
\begin{tikzcd}
0 \arrow[r] & {\mathcal{J}} \arrow[r] & {\mathcal{A}} \arrow[r, "q"] & {\mathcal{A}}/{\mathcal{J}} \arrow[r] & 0 
\end{tikzcd}
\end{equation*}
be a locally split short exact sequence. 
Then for any C*-algebra ${\mathcal{B}}$ we have that the sequence
\begin{equation*}
\begin{tikzcd}
0 \arrow[r] & {\mathcal{J}}\otimes {\mathcal{B}} \arrow[r] & {\mathcal{A}}\otimes {\mathcal{B}} \arrow[r, "q\otimes {\operatorname{id}}_{{\mathcal{B}}}"] & ({\mathcal{A}}/{\mathcal{J}})\otimes {\mathcal{B}} \arrow[r] & 0 
\end{tikzcd}
\end{equation*}
is short exact.

\label{T:Exlocunital}\cite[unital version of Theorem 10.2.4]{BO08}
Let ${\mathcal{A}}$ be a unital C*-algebra and for an ideal ${\mathcal{J}} \lhd {\mathcal{A}}$ let
\begin{equation*}
\begin{tikzcd}
0 \arrow[r] & {\mathcal{J}} \arrow[r] & {\mathcal{A}} \arrow[r, "q"] & {\mathcal{A}}/{\mathcal{J}} \arrow[r] & 0 
\end{tikzcd}
\end{equation*}
be a short exact sequence with ${\mathcal{J}}$ and ${\mathcal{A}}/{\mathcal{J}}$ exact. 
The following are equivalent:
\begin{enumerate}
\item The short exact sequence is locally split.
\item For every finite-dimensional unital operator system $E \subseteq {\mathcal{A}}/{\mathcal{J}}$ there exists a unital completely positive map $\theta \colon E \to {\mathcal{A}}$ such that $q \circ \theta = {\operatorname{id}}_E$.
\item For every finite-dimensional unital operator system $E \subseteq {\mathcal{A}}/{\mathcal{J}}$ there exists a completely contractive completely positive map $\theta \colon E \to {\mathcal{A}}$ such that $q \circ \theta = {\operatorname{id}}_E$.
\item ${\mathcal{A}}$ is exact.
\end{enumerate}

\label{T:Exlocgen}\cite[Theorem 10.2.4]{BO08}
Let ${\mathcal{A}}$ be a C*-algebra and for an ideal ${\mathcal{J}} \lhd {\mathcal{A}}$ let
\begin{equation*}
\begin{tikzcd}
0 \arrow[r] & {\mathcal{J}} \arrow[r] & {\mathcal{A}} \arrow[r, "q"] & {\mathcal{A}}/{\mathcal{J}} \arrow[r] & 0 
\end{tikzcd}
\end{equation*}
be a short exact sequence with ${\mathcal{J}}$ and ${\mathcal{A}}/{\mathcal{J}}$ exact. 
The following are equivalent:
\begin{enumerate}
\item The short exact sequence is locally split.
\item For every finite-dimensional selfadjoint subspace $E \subseteq {\mathcal{A}}/{\mathcal{J}}$ there exists a completely contractive completely positive map $\theta \colon E \to {\mathcal{A}}$ such that $q \circ \theta = {\operatorname{id}}_E$.
\item ${\mathcal{A}}$ is exact.
\end{enumerate}

\label{T:Exsum}
Let ${\mathcal{C}}$ be a C*-algebra and let ${\mathcal{J}}$ and ${\mathcal{A}}$ be C*-subalgebras of ${\mathcal{C}}$ such that ${\mathcal{J}} + {\mathcal{A}}$ is a C*-subalgebra of ${\mathcal{C}}$ and ${\mathcal{J}} \lhd {\mathcal{J}} + {\mathcal{A}}$.
If ${\mathcal{J}}$ and ${\mathcal{A}}$ are exact, then so is ${\mathcal{J}} + {\mathcal{A}}$.

\label{T:Nucsum}
Let ${\mathcal{C}}$ be a C*-algebra and let ${\mathcal{J}}$ and ${\mathcal{A}}$ be C*-subalgebras of ${\mathcal{C}}$ such that ${\mathcal{J}} + {\mathcal{A}}$ is a C*-subalgebra of ${\mathcal{C}}$ and ${\mathcal{J}} \lhd {\mathcal{J}} + {\mathcal{A}}$.
If ${\mathcal{J}}$ and ${\mathcal{A}}$ are nuclearly embedded in ${\mathcal{C}}$, then so is ${\mathcal{J}} + {\mathcal{A}}$.

\label{P:Kcoresiso}
\cite[Remark 3.3]{KP25}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $X$ be a product system over $P$.
Suppose that $t$ is an injective Fock covariant representation of $X$.
Then the canonical quotient map ${\mathcal{T}}_{\operatorname{c}}^{\operatorname{F}}(X) \to \mathrm{C}^*(t)$ restricts to a $*$-isomorphism on each $\mathbf{K}$-core.

\label{L:faj}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $X$ be a saturated product system over $P$.
For all $p, q, s, r, r_1, r_2 \in P$ the following hold:
\begin{enumerate}
\item $i^r_{p,q}$ is linear and contractive, and
$i^r_{p,q}(S)^* = i^r_{q,p}(S^*)$ for $S \in {\mathcal{L}}(X_q, X_p)$.
\item $i^r_{p,q}(S) \, i^r_{q,s}(T) = i^r_{p,s}(S T)$ for $S \in {\mathcal{L}}(X_q, X_p)$ and $T \in {\mathcal{L}}(X_s, X_q)$.
\item $i^{r_1 r_2}_{p,q}(S) = i^{r_2}_{p r_1, q r_1} \circ i^{r_1}_{p,q}(S)$ for $S \in {\mathcal{L}}(X_q, X_p)$.
\item $i^r_{p,q}(T S) = i_p^{pr}(T) \, i^r_{p,q}(S)$ and $i^r_{p,q}(S T') = i^r_{p,q}(S) \, i_q^{qr}(T')$, for $T \in {\mathcal{L}}(X_p)$, $T' \in {\mathcal{L}}(X_q)$ and $S \in {\mathcal{L}}(X_q, X_p)$.
\end{enumerate}

\label{L:faunits}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $X$ be a saturated product system over $P$.
If $z \in P^*$, then the following hold:
\begin{enumerate}
\item $\varphi_z(A) \subseteq {\mathcal{K}}(X_z)$;
\item $i^z_{p,q}\left( {\mathcal{K}}(X_q, X_p) \right) \subseteq {\mathcal{K}}(X_{qz}, X_{pz})$ for
all $p, q \in P$.
\end{enumerate}

\label{L:fadiag}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $X$ be a saturated product system over $P$.
If ${\mathbf{x}} \in {\mathcal{J}}$ and $b \in \mathbf{K}_{{\mathbf{x}}, \lambda_\ast}$, then the following hold:
\begin{enumerate}
\item $b X_r \subseteq X_r$ for $r \in {\mathbf{x}}$ and $b X_r = (0)$ for $r \notin {\mathbf{x}}$; in particular $b$ is determined by the family $(\operatorname{ev}_r(b))_{r \in {\mathbf{x}}}$, and each $\operatorname{ev}_r$ restricts to a $*$-homomorphism on $\mathbf{K}_{{\mathbf{x}}, \lambda_\ast}$.
\item $\operatorname{ev}_{rs}(b) = i_r^{rs}(\operatorname{ev}_r(b))$ for all $r \in {\mathbf{x}}$ and $s \in P$.
\end{enumerate}

\label{T:Kcores}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $X$ be a product system over $P$.
Let $t$ be a representation of $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathbf{K}_{{\mathbf{x}},t_\ast}$ is exact for every ${\mathbf{x}} \in {\mathcal{J}}$.
\item $\mathbf{B}_{{\mathcal{F}},t_\ast}$ is exact for every finite and $\cap$-closed ${\mathcal{F}} \subseteq {\mathcal{J}}$.
\item The inductive limit of the $\mathbf{B}_{{\mathcal{F}}, t_\ast}$ over the finite $\cap$-closed $\emptyset\in{\mathcal{F}}\subseteq{\mathcal{J}}$ is exact.
\end{enumerate}

\label{C:Excores-1}
Let $P$ be a unital subsemigroup of an amenable discrete group $G$ and let $X$ be a product system over $P$.
Let $t$ be an equivariant representation of $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathbf{K}_{{\mathbf{x}},t_\ast}$ is exact for every ${\mathbf{x}} \in {\mathcal{J}}$.
\item $\mathbf{B}_{{\mathcal{F}},t_\ast}$ is exact for every finite and $\cap$-closed ${\mathcal{F}} \subseteq {\mathcal{J}}$.
\item $[\mathrm{C}^*(t)]_{e_P}$ is exact.
\item $\mathrm{C}^*(t)$ is exact.
\end{enumerate}

\label{C:Excores-2}
Let $P$ be a unital subsemigroup of an amenable discrete group $G$ and let $X$ be a product system over $P$.
Then ${\mathcal{T}}_\lambda(X)$ is exact if and only if $\mathrm{C}^*(t)$ is exact for some (and thus for all) injective Fock covariant representation $t$ of $X$.

\label{C:exsem}
Let $P$ be a unital subsemigroup of an exact discrete group $G$.
Then the reduced C*-algebra $\mathrm{C}^*_\lambda(P)$ of the semigroup $P$ is exact.

\label{T:Nuccores}
Let $P$ be a unital subsemigroup of an amenable discrete group $G$ and let $X$ be a product system over $P$.
Let $t$ be an equivariant representation of $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathbf{K}_{{\mathbf{x}},t_\ast}$ is nuclearly embedded in $[\mathrm{C}^*(t)]_{e_P}$ for every ${\mathbf{x}} \in {\mathcal{J}}$.
\item $\mathbf{B}_{{\mathcal{F}},t_\ast}$ is nuclearly embedded in $[\mathrm{C}^*(t)]_{e_P}$ for every finite and $\cap$-closed ${\mathcal{F}} \subseteq {\mathcal{J}}$.
\item $[\mathrm{C}^*(t)]_{e_P}$ is nuclear.
\item $\mathrm{C}^*(t)$ is nuclear.
\end{enumerate}

\cite[Theorem 5.6.44]{CELY17}, \cite[Corollary 4.10]{LS22}\label{C:nucsem}
Let $P$ be a unital subsemigroup of an amenable discrete group $G$.
Then $\mathrm{C}^*_\lambda(P)$ is nuclear.

\label{P:fajfg}
Let $P$ be a unital subsemigroup of a discrete group $G$.
Then the following are equivalent:
\begin{enumerate}
\item $P$ is finitely aligned.
\item Every constructible ideal ${\mathbf{x}}\in {\mathcal{J}}$ is finitely generated.
\end{enumerate}

\label{D:mcm}
Let $P$ be a unital subsemigroup of a discrete group $G$ and let $p, q$ be in $P$.
An element $w \in pP \cap qP$ is a \emph{minimal common right multiple} of $p$ and $q$ if $w \in zP$ for $z \in pP \cap qP$ implies $w P = z P$ (and so $w=zx$ for some $x \in P^\ast$).

\label{P:famain}
Let $P$ be a unital finitely aligned subsemigroup of a discrete group $G$ and let $X$ be a compactly aligned saturated product system over $P$ with coefficient C*-algebra $A$.
If $A$ is exact, then $\mathbf{K}_{{\mathbf{x}}, \lambda_\ast}$ is exact for every ${\mathbf{x}} \in {\mathcal{J}}$.

\label{T:faexact}
Let $P$ be a unital finitely aligned subsemigroup of an exact discrete group $G$ and let $X$ be a compactly aligned saturated product system over $P$ with coefficient C*-algebra $A$.
Then the following are equivalent:
\begin{enumerate}
\item $A$ is exact.
\item ${\mathcal{T}}_\lambda(X)$ is exact.
\end{enumerate}
If in addition $G$ is amenable, then any of the items above is equivalent to the following:
\begin{enumerate}[resume]
\item $\mathrm{C}^*(t)$ is exact for an injective Fock covariant representation $t$ of $X$.
\end{enumerate}

\label{P:sfa}
Let $P$ be a unital subsemigroup of a discrete group $G$.
Then the following are equivalent:
\begin{enumerate}
\item $P$ is strongly finitely aligned.
\item Every ${\mathbf{x}}\in {\mathcal{J}}$ is a disjoint union of finitely many principal right ideals.
\end{enumerate}

\label{T:fanuc}
Let $P$ be a unital strongly finitely aligned subsemigroup of an amenable discrete group $G$ and let $X$ be a compactly aligned saturated product system over $P$ with coefficient C*-algebra $A$.
Let $t$ be an injective equivariant Fock covariant representation of $X$.
Then the following are equivalent:
\begin{enumerate}
\item The embedding $A \hookrightarrow [\mathrm{C}^*(t)]_{e_P}$ is nuclear.
\item The embedding $\mathbf{K}_{{\mathbf{x}}, t_\ast} \hookrightarrow [\mathrm{C}^*(t)]_{e_P}$ is nuclear for every ${\mathbf{x}} \in {\mathcal{J}}$.
\item $\mathrm{C}^*(t)$ is nuclear.
\end{enumerate}

\label{C:fanuc}
Let $P$ be a unital strongly finitely aligned subsemigroup of an amenable discrete group $G$ and let $X$ be a compactly aligned saturated product system over $P$ with coefficient C*-algebra $A$.
Then ${\mathcal{T}}_\lambda(X)$ is nuclear if and only if $A$ is nuclear.
